40	/**
41	 * Decompose a *non-negative, finite* double into its shortest round-trip
42	 * decimal digits and CPython's `decpt` (position of the decimal point
43	 * relative to the start of the digit string).
44	 *
45	 * `Number.prototype.toExponential()` called with **no argument** yields
46	 * "as many digits as necessary to uniquely specify the Number" — exactly
47	 * the shortest round-trip digit string that CPython's `_Py_dg_dtoa(…, 0, 0, …)`
48	 * produces. The result always looks like `d[.ddd]e{+|-}dd`.
49	 */
50	function shortestDigits(a) {
51	  const s = a.toExponential();
52	  const ei = s.indexOf('e');
53	  const mant = s.slice(0, ei);
54	  const expPart = s.slice(ei + 1);
55	
56	  // --- exponent ---
57	  let esign = 1;
58	  let k = 0;
59	  const c0 = expPart.charAt(0);
60	  if (c0 === '+') k = 1;
61	  else if (c0 === '-') {
62	    esign = -1;
63	    k = 1;
64	  }
65	  let exp = 0;
66	  for (; k < expPart.length; k++) exp = exp * 10 + (expPart.charCodeAt(k) - 48);
67	  exp *= esign;
68	
69	  // --- mantissa digits, dot removed ---
70	  const dot = mant.indexOf('.');
71	  const digits = dot < 0 ? mant : mant.slice(0, dot) + mant.slice(dot + 1);
72	
73	  return { digits, decpt: exp + 1 };
74	}
75	
76	/** Zero-pad the absolute exponent to at least two digits. */
77	function padExp(n) {
78	  const s = String(n < 0 ? -n : n);
79	  return s.length >= 2 ? s : '0' + s;
80	}
81	
82	/**
83	 * Core of CPython's `format_float_short` for the 'r' (repr) mode.
84	 * `addDotZero` corresponds to the `Py_DTSF_ADD_DOT_0` flag: set for
85	 * `repr(float)`, clear for the components of `repr(complex)`.
86	 */
87	function floatShort(x, addDotZero) {
88	  if (Number.isNaN(x)) return 'nan';
89	  if (x === Infinity) return 'inf';
90	  if (x === -Infinity) return '-inf';
91	
92	  // -0.0 must keep its sign; Object.is distinguishes it from +0.0.
93	  const neg = x < 0 || Object.is(x, -0);
94	  const a = neg ? -x : x;
95	
96	  const { digits, decpt } = shortestDigits(a);
97	
98	  // CPython: use_exp = decpt <= -4 || decpt > 16  (16 == 'r' mode threshold)
99	  const useExp = decpt <= -4 || decpt > 16;
100	
101	  let body;
102	  if (useExp) {
103	    const e = decpt - 1;
104	    body =
105	      digits.charAt(0) +
106	      (digits.length > 1 ? '.' + digits.slice(1) : '') +
107	      'e' +
108	      (e >= 0 ? '+' : '-') +
109	      padExp(e);
110	  } else if (decpt <= 0) {
111	    body = '0.' + '0'.repeat(-decpt) + digits;
112	  } else if (decpt >= digits.length) {
113	    body = digits + '0'.repeat(decpt - digits.length) + (addDotZero ? '.0' : '');
114	  } else {
115	    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
116	  }
117	
118	  return neg ? '-' + body : body;
119	}
120	
121	/** CPython `repr(float)`. */
122	export function pyFloatRepr(x) {
123	  return floatShort(x, true);
124	}
