135	/**
136	 * Non-printable code point ranges above U+007F.
137	 *
138	 * CPython's `str.isprintable()` is false for Unicode categories
139	 * Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs (SPACE itself is printable).
140	 * A complete Cn (unassigned) table would be enormous, so this covers the
141	 * whole of Cc/Cf/Cs/Co/Zs/Zl/Zp plus the noncharacter blocks and the
142	 * unassigned gaps in the low planes. Deep-plane unassigned code points may
143	 * therefore be reported as printable where CPython escapes them; this only
144	 * affects `repr()` of exotic characters.
145	 */
146	const NONPRINTABLE_RANGES = [
147	  [0x80, 0x9f], // Cc  (C1 controls)
148	  [0xa0, 0xa0], // Zs  NBSP
149	  [0xad, 0xad], // Cf  SOFT HYPHEN
150	  [0x378, 0x379], // Cn
151	  [0x380, 0x383], // Cn
152	  [0x38b, 0x38b],
153	  [0x38d, 0x38d],
154	  [0x3a2, 0x3a2],
155	  [0x600, 0x605], // Cf  Arabic number signs
156	  [0x61c, 0x61c], // Cf  ARABIC LETTER MARK
157	  [0x6dd, 0x6dd], // Cf
158	  [0x70f, 0x70f], // Cf
159	  [0x890, 0x891], // Cf
160	  [0x8e2, 0x8e2], // Cf
161	  [0x1680, 0x1680], // Zs  OGHAM SPACE MARK
162	  [0x180e, 0x180e], // Cf  MONGOLIAN VOWEL SEPARATOR
163	  [0x2000, 0x200f], // Zs (2000-200A) + Cf (200B-200F)
164	  [0x2028, 0x2029], // Zl + Zp
165	  [0x202a, 0x202f], // Cf (202A-202E) + Zs (202F)
166	  [0x205f, 0x206f], // Zs (205F) + Cf/Cn (2060-206F)
167	  [0x3000, 0x3000], // Zs  IDEOGRAPHIC SPACE
168	  [0xd800, 0xf8ff], // Cs surrogates + Co private use
169	  [0xfdd0, 0xfdef], // Cn noncharacters
170	  [0xfeff, 0xfeff], // Cf  BOM / ZWNBSP
171	  [0xfff9, 0xfffb], // Cf  interlinear annotation
172	  [0xfffe, 0xffff], // Cn noncharacters
173	  [0x110bd, 0x110bd], // Cf
174	  [0x110cd, 0x110cd], // Cf
175	  [0x13430, 0x1343f], // Cf  Egyptian hieroglyph format controls
176	  [0x1bca0, 0x1bca3], // Cf  Shorthand format controls
177	  [0x1d173, 0x1d17a], // Cf  Musical symbol beams
178	  [0x1fffe, 0x1ffff], // Cn noncharacters
179	  [0x2fffe, 0x2ffff],
180	  [0x3fffe, 0x3ffff],
181	  [0x4fffe, 0x4ffff],
182	  [0x5fffe, 0x5ffff],
183	  [0x6fffe, 0x6ffff],
184	  [0x7fffe, 0x7ffff],
185	  [0x8fffe, 0x8ffff],
186	  [0x9fffe, 0x9ffff],
187	  [0xafffe, 0xaffff],
188	  [0xbfffe, 0xbffff],
189	  [0xcfffe, 0xcffff],
190	  [0xdfffe, 0xdffff],
191	  [0xe0001, 0xe0001], // Cf  LANGUAGE TAG
192	  [0xe0020, 0xe007f], // Cf  tag characters
193	  [0xefffe, 0xeffff], // Cn
194	  [0xf0000, 0x10ffff], // Co planes 15/16 + their noncharacters
195	];
196	
197	function isPrintableCp(cp) {
198	  if (cp < 0x20) return false; // C0 controls
199	  if (cp < 0x7f) return true; // SPACE .. '~'
200	  if (cp === 0x7f) return false; // DEL
201	  for (let i = 0; i < NONPRINTABLE_RANGES.length; i++) {
202	    const r = NONPRINTABLE_RANGES[i];
203	    if (cp < r[0]) break; // table is ascending
204	    if (cp <= r[1]) return false;
205	  }
206	  return true;
207	}
