213	const HEX_LOWER = '0123456789abcdef';
214	
215	/** Lowercase, zero-padded hex — CPython's repr uses lowercase hex digits. */
216	function hexLower(n, width) {
217	  let s = '';
218	  let v = n;
219	  while (v > 0) {
220	    s = HEX_LOWER.charAt(v & 0xf) + s;
221	    v = Math.floor(v / 16);
222	  }
223	  while (s.length < width) s = '0' + s;
224	  return s;
225	}
