227	/**
228	 * CPython `unicode_repr`: single quotes are preferred; double quotes are used
229	 * only when the string contains a `'` and no `"`. The *other* quote character
230	 * is never escaped.
231	 */
232	export function pyStrRepr(s) {
233	  const cps = codePoints(s);
234	
235	  let hasSingle = false;
236	  let hasDouble = false;
237	  for (let i = 0; i < cps.length; i++) {
238	    if (cps[i] === 0x27) hasSingle = true;
239	    else if (cps[i] === 0x22) hasDouble = true;
240	  }
241	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
242	  const quoteCh = quote === 0x22 ? '"' : "'";
243	
244	  let out = quoteCh;
245	  for (let i = 0; i < cps.length; i++) {
246	    const cp = cps[i];
247	    if (cp === quote || cp === 0x5c) {
248	      out += '\\' + String.fromCharCode(cp);
249	    } else if (cp === 0x09) out += '\\t';
250	    else if (cp === 0x0a) out += '\\n';
251	    else if (cp === 0x0d) out += '\\r';
252	    else if (isPrintableCp(cp)) out += fromCodePoint(cp);
253	    else if (cp < 0x100) out += '\\x' + hexLower(cp, 2);
254	    else if (cp < 0x10000) out += '\\u' + hexLower(cp, 4);
255	    else out += '\\U' + hexLower(cp, 8);
256	  }
257	  return out + quoteCh;
258	}
