264	/**
265	 * CPython `bytes_repr`: `b` prefix, same quote-choice rule as str, only
266	 * `\t \n \r \\` and the active quote are named escapes, everything outside
267	 * printable ASCII becomes `\xHH`.
268	 */
269	export function pyBytesRepr(b) {
270	  const bs = b.bytes;
271	  let hasSingle = false;
272	  let hasDouble = false;
273	  for (let i = 0; i < bs.length; i++) {
274	    if (bs[i] === 0x27) hasSingle = true;
275	    else if (bs[i] === 0x22) hasDouble = true;
276	  }
277	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
278	  const quoteCh = quote === 0x22 ? '"' : "'";
279	
280	  let out = 'b' + quoteCh;
281	  for (let i = 0; i < bs.length; i++) {
282	    const c = bs[i];
283	    if (c === quote || c === 0x5c) out += '\\' + String.fromCharCode(c);
284	    else if (c === 0x09) out += '\\t';
285	    else if (c === 0x0a) out += '\\n';
286	    else if (c === 0x0d) out += '\\r';
287	    else if (c >= 0x20 && c < 0x7f) out += String.fromCharCode(c);
288	    else out += '\\x' + hexLower(c, 2);
289	  }
290	  return out + quoteCh;
291	}
