297	/**
298	 * CPython `complex_repr`. Note both components are formatted **without**
299	 * `Py_DTSF_ADD_DOT_0`, so `complex(1, 2)` is `(1+2j)`, not `(1.0+2.0j)`.
300	 * PyYAML's `represent_complex` uses plain `%r` on the parts instead, which
301	 * is why it keeps the `.0` — that lives in the representer, not here.
302	 */
303	export function pyComplexRepr(c) {
304	  // "Real part is +0" -> print only the imaginary part, no parentheses.
305	  if (c.re === 0 && !Object.is(c.re, -0)) {
306	    return floatShort(c.im, false) + 'j';
307	  }
308	  const re = floatShort(c.re, false);
309	  let im = floatShort(c.im, false);
310	  // Py_DTSF_SIGN on the imaginary part: always emit an explicit sign.
311	  if (im.charAt(0) !== '-') im = '+' + im;
312	  return '(' + re + im + 'j)';
313	}
