319	/** A plausible stand-in for CPython's `0x…` object addresses. */
320	function fakeAddress(v) {
321	  const id = objectId(v);
322	  const n = typeof id === 'number' ? id : 1;
323	  return '0x' + (0x7f0000000000 + n * 16).toString(16);
324	}
