326	/**
327	 * CPython `repr()` for every value in the value model.
328	 * `seen` guards against self-referential containers, which CPython renders
329	 * as `[...]` / `{...}` / `(...)`.
330	 */
331	export function pyRepr(v, seen) {
332	  if (typeof v === 'string') return pyStrRepr(v);
333	  if (typeof v === 'bigint') return pyIntRepr(v);
334	  if (typeof v === 'number') return pyFloatRepr(v);
335	  if (v instanceof PyBool) return v.value ? 'True' : 'False';
336	  if (v instanceof PyNone) return 'None';
337	  if (v instanceof PyEllipsis) return 'Ellipsis';
338	  if (v instanceof PyBytes) return pyBytesRepr(v);
339	  if (v instanceof PyComplex) return pyComplexRepr(v);
340	  if (v instanceof PyRange) {
341	    return (
342	      'range(' +
343	      v.start.toString() +
344	      ', ' +
345	      v.stop.toString() +
346	      (v.step === 1n ? '' : ', ' + v.step.toString()) +
347	      ')'
348	    );
349	  }
350	  if (v instanceof PySlice) {
351	    return (
352	      'slice(' + pyRepr(v.start) + ', ' + pyRepr(v.stop) + ', ' + pyRepr(v.step) + ')'
353	    );
354	  }
355	
356	  const marks = seen || new Set();
357	
358	  if (v instanceof PyList) {
359	    if (marks.has(v)) return '[...]';
360	    marks.add(v);
361	    const parts = v.items.map((it) => pyRepr(it, marks));
362	    marks.delete(v);
363	    return '[' + parts.join(', ') + ']';
364	  }
365	  if (v instanceof PyTuple) {
366	    if (marks.has(v)) return '(...)';
367	    marks.add(v);
368	    const parts = v.items.map((it) => pyRepr(it, marks));
369	    marks.delete(v);
370	    // A 1-tuple keeps a trailing comma so it round-trips.
371	    if (parts.length === 1) return '(' + parts[0] + ',)';
372	    return '(' + parts.join(', ') + ')';
373	  }
374	  if (v instanceof PyFrozenSet) {
375	    if (v.size === 0) return 'frozenset()';
376	    if (marks.has(v)) return 'frozenset({...})';
377	    marks.add(v);
378	    const parts = v.values().map((it) => pyRepr(it, marks));
379	    marks.delete(v);
380	    return 'frozenset({' + parts.join(', ') + '})';
381	  }
382	  if (v instanceof PySet) {
383	    // Empty sets have no literal syntax, so CPython prints the constructor.
384	    if (v.size === 0) return 'set()';
385	    if (marks.has(v)) return '{...}';
386	    marks.add(v);
387	    const parts = v.values().map((it) => pyRepr(it, marks));
388	    marks.delete(v);
389	    return '{' + parts.join(', ') + '}';
390	  }
391	  if (v instanceof PyDict) {
392	    if (v.size === 0) return '{}';
393	    if (marks.has(v)) return '{...}';
394	    marks.add(v);
395	    const parts = v.entries().map(([k, val]) => pyRepr(k, marks) + ': ' + pyRepr(val, marks));
396	    marks.delete(v);
397	    return '{' + parts.join(', ') + '}';
398	  }
399	
400	  if (v instanceof PyBuiltin) return '<built-in function ' + v.name + '>';
401	  if (v instanceof PyBoundMethod) {
402	    return '<built-in method ' + v.name + ' of object at ' + fakeAddress(v) + '>';
403	  }
404	  if (v instanceof PyFunction) {
405	    return '<function ' + (v.name || '<lambda>') + ' at ' + fakeAddress(v) + '>';
406	  }
407	  if (v instanceof PyObject) {
408	    // `repr(object())` -> '<object object at 0x…>'
409	    const short = v.clsName.slice(v.clsName.lastIndexOf('.') + 1);
410	    return '<' + short + ' object at ' + fakeAddress(v) + '>';
411	  }
412	  return '<object at ' + fakeAddress(v) + '>';
413	}
