421	/* ================================================================== *
422	 * base64.encodebytes
423	 * ================================================================== */
424	
425	const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
426	
427	/**
428	 * `base64.encodebytes(data).decode('ascii')`.
429	 *
430	 * Lib/base64.py feeds 57 input bytes at a time to `binascii.b2a_base64`,
431	 * each chunk producing 76 output characters plus a '\n'. Empty input gives
432	 * the empty string (no newline at all).
433	 */
434	export function base64Encodebytes(u8) {
435	  const n = u8.length;
436	  if (n === 0) return '';
437	
438	  let out = '';
439	  let col = 0;
440	  const push = (ch) => {
441	    out += ch;
442	    col++;
443	    if (col === 76) {
444	      out += '\n';
445	      col = 0;
446	    }
447	  };
448	
449	  let i = 0;
450	  for (; i + 2 < n; i += 3) {
451	    const w = (u8[i] << 16) | (u8[i + 1] << 8) | u8[i + 2];
452	    push(B64_ALPHABET.charAt((w >> 18) & 0x3f));
453	    push(B64_ALPHABET.charAt((w >> 12) & 0x3f));
454	    push(B64_ALPHABET.charAt((w >> 6) & 0x3f));
455	    push(B64_ALPHABET.charAt(w & 0x3f));
456	  }
457	  const rest = n - i;
458	  if (rest === 1) {
459	    const w = u8[i] << 16;
460	    push(B64_ALPHABET.charAt((w >> 18) & 0x3f));
461	    push(B64_ALPHABET.charAt((w >> 12) & 0x3f));
462	    push('=');
463	    push('=');
464	  } else if (rest === 2) {
465	    const w = (u8[i] << 16) | (u8[i + 1] << 8);
466	    push(B64_ALPHABET.charAt((w >> 18) & 0x3f));
467	    push(B64_ALPHABET.charAt((w >> 12) & 0x3f));
468	    push(B64_ALPHABET.charAt((w >> 6) & 0x3f));
469	    push('=');
470	  }
471	
472	  // Every chunk is newline-terminated, so a partial final line still gets one.
473	  if (col !== 0) out += '\n';
474	  return out;
475	}
